// Shared catalogue-HTML builder. ONE source of truth: this exact function body is pasted into the
// n8n Code node (make_workflow_d7.py). It takes product rows and returns ONE print-ready HTML
// document (A4), grouped by category: a cover page + a card per product with its price. No AI, no
// external module — plain string building. SAMPLE DATA stays in the cover + the running footer.
function buildCatalogHTML(rows, shop) {
  const esc = s => String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const AR = '٠١٢٣٤٥٦٧٨٩';
  const toAr = n => String(n).replace(/[0-9]/g, d => AR[+d]);  // price digits -> Eastern Arabic

  // group by category, preserving first-seen order
  const order = [], byCat = {};
  for (const r of rows) {
    const c = r.category || 'أخرى';
    if (!(c in byCat)) { byCat[c] = []; order.push(c); }
    byCat[c].push(r);
  }

  const card = r => `
      <div class="card">
        <div class="sku">${esc(r.sku)}</div>
        <div class="pname">${esc(r.product)}</div>
        <div class="pdesc">${esc(r.desc)}</div>
        <div class="prow">
          <span class="price">${toAr(r.price)}</span>
          <span class="unit">${esc(r.unit)}</span>
        </div>
      </div>`;

  const section = (c, i) => `
    <section class="cat${i === 0 ? ' first' : ''}">
      <div class="cathead"><span class="catname">${esc(c)}</span>
        <span class="catcount">${toAr(byCat[c].length)} منتج</span></div>
      <div class="grid">${byCat[c].map(card).join('')}</div>
    </section>`;

  const total = rows.length;
  const cats = order.length;
  const body = order.map(section).join('');

  return `<!doctype html>
<html dir="rtl" lang="ar"><head><meta charset="utf-8"><style>
@page { size: A4; margin: 0; }
* { box-sizing: border-box; margin: 0; padding: 0; }
html, body { font-family: "Noto Kufi Arabic","Noto Naskh Arabic","DejaVu Sans",sans-serif; color:#1b2330; }
body { padding-bottom: 20mm; }
.cover {
  height: 297mm; background:#0E1118; color:#F2F4F8; display:flex; flex-direction:column;
  align-items:center; justify-content:center; text-align:center; break-after: page; position:relative;
}
.cover .bar { width:70mm; height:3mm; background:#FFB800; border-radius:2mm; margin:9mm 0; }
.cover .shop { font-size:30pt; font-weight:800; color:#FFB800; letter-spacing:.3pt; }
.cover .ttl { font-size:21pt; font-weight:700; margin-top:5mm; }
.cover .sub { font-size:13pt; color:#AEB8CC; margin-top:7mm; }
.cover .meta { font-size:12pt; color:#8A96AE; margin-top:3mm; }
.cover .ribbon {
  position:absolute; top:16mm; left:50%; transform:translateX(-50%);
  border:1.4pt solid #FFB800; color:#FFD766; font-size:11pt; font-weight:700;
  padding:2mm 7mm; border-radius:6mm; letter-spacing:.4pt;
}
.cat { padding: 10mm 14mm 0; break-inside: avoid; }
.cat.first { padding-top: 12mm; }
.cathead {
  display:flex; align-items:center; justify-content:space-between;
  background:#141A28; color:#fff; border-radius:3mm; padding:3.4mm 6mm; margin-bottom:6mm;
  border-right:3mm solid #FFB800;
}
.cathead .catname { font-size:16pt; font-weight:800; }
.cathead .catcount { font-size:10.5pt; color:#FFD766; font-weight:700; }
.grid { display:grid; grid-template-columns:1fr 1fr; gap:6mm; }
.card {
  position:relative; background:#fff; border:0.5pt solid #E2E6EE; border-radius:3mm;
  padding:6mm 6mm 5mm; box-shadow:0 0.6mm 2mm rgba(20,26,40,.06); break-inside: avoid; overflow:hidden;
}
.card::before { content:""; position:absolute; top:0; right:0; width:3mm; height:100%; background:#FFB800; opacity:.9; }
.card .sku { position:absolute; top:4mm; left:6mm; font-size:8.5pt; color:#9AA6BC; direction:ltr; letter-spacing:.4pt; }
.card .pname { font-size:14.5pt; font-weight:800; color:#17202E; margin-bottom:2mm; padding-left:16mm; }
.card .pdesc { font-size:10.5pt; color:#5B6678; line-height:1.5; min-height:11mm; }
.prow { display:flex; align-items:center; gap:4mm; margin-top:3mm; }
.price {
  background:#FFB800; color:#1b2330; font-size:16pt; font-weight:800; border-radius:6mm;
  padding:1.6mm 7mm; min-width:18mm; text-align:center;
}
.unit { font-size:10pt; color:#6B7686; }
.foot {
  position: fixed; bottom: 0; left: 0; right: 0; height: 13mm;
  display:flex; align-items:center; justify-content:space-between; padding:0 14mm;
  font-size:9.5pt; color:#8A96AE; border-top:0.5pt solid #E2E6EE; background:#fff;
}
.foot .sd { color:#B9803A; font-weight:700; }
</style></head>
<body>
  <div class="cover">
    <div class="ribbon">بيانات تجريبية · SAMPLE DATA</div>
    <div class="shop">${esc(shop)}</div>
    <div class="bar"></div>
    <div class="ttl">قائمة المنتجات والأسعار</div>
    <div class="sub">${toAr(total)} منتجاً في ${toAr(cats)} فئات</div>
    <div class="meta">الأسعار بعملتك · كتالوج أُنشئ تلقائياً بـ n8n</div>
  </div>
  ${body}
  <div class="foot"><span>${esc(shop)} · قائمة الأسعار</span><span class="sd">بيانات تجريبية — SAMPLE DATA</span></div>
</body></html>`;
}

// ---- n8n wrapper: map the Arabic columns of the price list -> builder rows, return catalog.html ----
const rows = $input.all().map(i => i.json).map(r => ({
  category: r['الفئة'],
  product:  r['المنتج'],
  desc:     r['وصف مختصر'],
  price:    r['السعر'],
  unit:     r['الوحدة'],
  sku:      r['الرمز'],
}));
const shop = 'متجر السنابل';
const html = buildCatalogHTML(rows, shop);
const cats = [...new Set(rows.map(r => r.category))];
const bin = await this.helpers.prepareBinaryData(Buffer.from(html, 'utf8'),
  'catalog.html', 'text/html');
return [{ json: { products: rows.length, categories: cats.length, file: 'catalog.html' },
  binary: { data: bin } }];
